  public synchronized List<StructClass> getOwnClasses() {
    List<StructClass> result = new ArrayList<>();
    for (Map.Entry<String, List<ContextUnit>> entry : this.eagerCandidates.entrySet()) {
      if (entry.getValue().stream().anyMatch(ContextUnit::isOwn)) {
        StructClass clazz = Objects.requireNonNull(this.getClass(entry.getKey()), () -> "Could not find class " + entry.getKey());
