  private void initUnit(final ContextUnit unit) {
    DecompilerContext.getLogger().writeMessage("Scanning classes from " + unit.getName(), IFernflowerLogger.Severity.INFO);
    for (final String clazz : unit.getClassNames()) {
      List<ContextUnit> candidates = this.eagerCandidates.computeIfAbsent(clazz, ignored -> new ArrayList<>());
      if (!candidates.contains(unit)) {
        candidates.add(unit);
      }
      DecompilerContext.getLogger().writeMessage("    " + clazz, IFernflowerLogger.Severity.TRACE);
    }

    for (final IContextSource child : unit.getChildContexts()) {
      this.addSpace(child, unit.isOwn(), false);
    }
  }

  private void invalidateForAddedUnit(ContextUnit unit) {
    if (unit.isOwn()) {
      this.classes.clear();
      this.selections.clear();
      this.familyParents.clear();
      this.activeFamilies.clear();
      this.familyAnchors.clear();
      this.familyMetadataInitialized = false;
      return;
    }

    if (unit.isLazy()) {
      this.classes.keySet().removeIf(name -> {
        Selection selection = this.selections.get(name);
        return selection == null || !selection.unit.isOwn();
      });
      this.selections.entrySet().removeIf(entry -> !entry.getValue().unit.isOwn());
      return;
    }

    for (String name : unit.getClassNames()) {
      Selection selection = this.selections.get(name);
      if (selection == null || !selection.unit.isOwn()) {
        this.classes.remove(name);
        this.selections.remove(name);
      }
    }
  }

  private void clearResolutionState() {
    this.classes.clear();
    this.selections.clear();
    this.classBytes.clear();
    this.familyParents.clear();
    this.activeFamilies.clear();
    this.familyAnchors.clear();
    this.familyMetadataInitialized = false;
  }

  private Selection select(String name) {
    Selection cached = this.selections.get(name);
    if (cached != null) {
      return cached;
    }

    List<Candidate> candidates = candidates(name);
    if (candidates.isEmpty()) {
      return null;
    }

    List<Candidate> ownCandidates = candidates.stream().filter(candidate -> candidate.unit.isOwn()).toList();
    List<Candidate> eligible = ownCandidates.isEmpty() ? candidates.stream().filter(candidate -> !candidate.unit.isOwn()).toList() : ownCandidates;
    if (eligible.isEmpty()) {
      return null;
    }

    ContextUnit requiredOrigin = null;
    String familyRoot = null;
    if (!ownCandidates.isEmpty()) {
      initializeFamilyMetadata();
      familyRoot = familyRoot(name);
      String duplicate = this.activeFamilies.get(familyRoot);
      if (duplicate != null) {
        requiredOrigin = this.familyAnchors.get(familyRoot);
        if (requiredOrigin == null) {
          Selection anchorSelection;
          List<Candidate> rootCandidates = ownCandidates(familyRoot);
          if (!rootCandidates.isEmpty()) {
            anchorSelection = chooseCandidate(familyRoot, rootCandidates, familyRoot, null);
            this.selections.put(familyRoot, anchorSelection);
          } else {
            anchorSelection = chooseCandidate(duplicate, ownCandidates(duplicate), familyRoot, null);
            this.selections.put(duplicate, anchorSelection);
          }
          requiredOrigin = anchorSelection.unit;
          this.familyAnchors.put(familyRoot, requiredOrigin);
          Selection selectedDuringAnchoring = this.selections.get(name);
          if (selectedDuringAnchoring != null) {
            return selectedDuringAnchoring;
          }
        }
      }
    }

    Selection selection = chooseCandidate(name, eligible, familyRoot, requiredOrigin);
    this.selections.put(name, selection);
    return selection;
  }

  private Selection chooseCandidate(String name, List<Candidate> candidates, String familyRoot, ContextUnit requiredOrigin) {
    DuplicateClassStrategy strategy = DuplicateClassStrategy.parse(DecompilerContext.getProperty(IFernflowerPreferences.DUPLICATE_CLASS_STRATEGY));
    boolean differing = candidates.stream().skip(1).anyMatch(candidate -> !Arrays.equals(candidates.get(0).bytes, candidate.bytes));
    if (strategy == DuplicateClassStrategy.ERROR && differing) {
      String origins = candidates.stream().map(candidate -> originName(candidate.unit)).collect(Collectors.joining(", "));
      String message = "Conflicting class " + name + " in highest-precedence origins: " + origins;
      DecompilerContext.getLogger().writeMessage(message, IFernflowerLogger.Severity.ERROR);
      throw new IllegalStateException(message);
    }

    Candidate selected;
    if (requiredOrigin != null) {
      selected = candidates.stream().filter(candidate -> candidate.unit == requiredOrigin).findFirst().orElse(null);
      if (selected == null) {
        String alternatives = candidates.stream().map(candidate -> originName(candidate.unit)).collect(Collectors.joining(", "));
        String message = "Class family " + familyRoot + " is anchored to " + originName(requiredOrigin) +
          ", but member " + name + " is available only from own origins: " + alternatives;
        DecompilerContext.getLogger().writeMessage(message, IFernflowerLogger.Severity.ERROR);
        throw new IllegalStateException(message);
      }
    } else if (strategy == DuplicateClassStrategy.LAST) {
      selected = candidates.get(candidates.size() - 1);
    } else {
      selected = candidates.get(0);
    }

    if (differing && strategy != DuplicateClassStrategy.ERROR) {
      Candidate winner = selected;
      String ignored = candidates.stream()
        .filter(candidate -> candidate.unit != winner.unit)
        .map(candidate -> originName(candidate.unit))
        .collect(Collectors.joining(", "));
      String root = familyRoot == null ? name : familyRoot;
      DecompilerContext.getLogger().writeMessage(
        "Duplicate class " + name + " resolved with strategy " + strategy.optionValue() +
          ": selected " + originName(selected.unit) + "; ignored " + ignored + "; metadata family root " + root,
        IFernflowerLogger.Severity.WARN
      );
    }

    return new Selection(selected.unit, selected.bytes);
  }

  private List<Candidate> candidates(String name) {
    List<ContextUnit> eager = this.eagerCandidates.getOrDefault(name, List.of());
    boolean hasOwn = eager.stream().anyMatch(ContextUnit::isOwn);
    List<Candidate> result = new ArrayList<>();
    for (ContextUnit unit : this.units) {
      if (hasOwn) {
        if (!unit.isOwn() || !eager.contains(unit)) {
          continue;
        }
      } else if (!eager.contains(unit) && !unit.isLazy()) {
        continue;
      }

      byte[] bytes = readBytes(unit, name);
      byte[] bytes = readBytes(unit, name);
      if (bytes != null) {
        result.add(new Candidate(unit, bytes));
      }
    }
    return result;
  }

  private List<Candidate> ownCandidates(String name) {
    return candidates(name).stream().filter(candidate -> candidate.unit.isOwn()).toList();
  }

  private byte @Nullable [] readBytes(ContextUnit unit, String name) {
    Probe probe = new Probe(unit, name);
    Optional<byte[]> cached = this.classBytes.get(probe);
    if (cached != null) {
      return cached.orElse(null);
    }

    try {
      byte[] bytes = unit.getClassBytes(name);
      this.classBytes.put(probe, Optional.ofNullable(bytes));
      return bytes;
    } catch (IOException exception) {
      DecompilerContext.getLogger().writeMessage("Failed to read class " + name + " from " + originName(unit), IFernflowerLogger.Severity.ERROR, exception);
      this.classBytes.put(probe, Optional.empty());
      return null;
    }
  }

  private void initializeFamilyMetadata() {
    if (this.familyMetadataInitialized) {
