    this.familyMetadataInitialized = true;

    for (Map.Entry<String, List<ContextUnit>> entry : this.eagerCandidates.entrySet()) {
      for (ContextUnit unit : entry.getValue()) {
        if (!unit.isOwn()) {
          continue;
        }
        byte[] bytes = readBytes(unit, entry.getKey());
        if (bytes == null) {
          continue;
        }
        try {
          StructClass clazz = StructClass.create(new DataInputFullStream(bytes), true);
          StructInnerClassesAttribute innerClasses = clazz.getAttribute(StructGeneralAttribute.ATTRIBUTE_INNER_CLASSES);
          if (innerClasses != null) {
            for (StructInnerClassesAttribute.Entry inner : innerClasses.getEntries()) {
              if (inner.innerName != null && inner.enclosingName != null && !inner.innerName.equals(inner.enclosingName)) {
                this.familyParents.putIfAbsent(inner.innerName, inner.enclosingName);
