            this.familyParents.putIfAbsent(clazz.qualifiedName, enclosingMethod.getClassName());
          }
        } catch (IOException exception) {
          DecompilerContext.getLogger().writeMessage("Failed to inspect class family metadata for " + entry.getKey() + " from " + originName(unit), IFernflowerLogger.Severity.ERROR, exception);
        }
      }
    }

    for (Map.Entry<String, List<ContextUnit>> entry : this.eagerCandidates.entrySet()) {
      long ownOrigins = entry.getValue().stream().filter(ContextUnit::isOwn).distinct().count();
      if (ownOrigins > 1) {
