  private String familyRoot(String name) {
    String current = name;
    Set<String> visited = new LinkedHashSet<>();
    while (visited.add(current)) {
      String parent = this.familyParents.get(current);
      if (parent == null) {
        return current;
      }
      current = parent;
    }
    return visited.iterator().next();
  }

